#!/usr/bin/env node
/**
 * Generates data/registry.generated.ts from the backend's verified selection.
 *
 *   backend/registry/selected.json            → which assets and which feed (source of truth)
 *   backend/registry/input/commonAssets.ts    → metadata (name, decimals, address, logo, feed tags)
 *
 * Joins on the canonical "<chainId>:<lowercase address>" ID. Fails if any selected
 * record lacks metadata or its selected feed. No runtime discovery.
 *
 * Usage: node scripts/generate-registry.mjs [--check]
 *   --check  exit 1 if the generated file is out of date instead of writing it.
 */
import {existsSync, readFileSync, writeFileSync} from 'node:fs';
import {dirname, join, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';

const web = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const backend = resolve(web, '../../../backend/registry');
const selectedPath = join(backend, 'selected.json');
const metadataPath = join(backend, 'input/commonAssets.ts');
const outputPath = join(web, 'data/registry.generated.ts');
const logoRoot = join(web, 'public');

function fail(message) {
  console.error(`generate-registry: ${message}`);
  process.exit(1);
}

for (const path of [selectedPath, metadataPath]) if (!existsSync(path)) fail(`missing ${path}`);

const selected = JSON.parse(readFileSync(selectedPath, 'utf8'));
if (selected.verified !== true || !Array.isArray(selected.assets)) fail('selected.json is not a verified selection');

const source = readFileSync(metadataPath, 'utf8');
const marker = 'export const COMMON_ASSETS = ';
const start = source.indexOf(marker);
if (start < 0) fail('COMMON_ASSETS not found in commonAssets.ts');
const end = source.indexOf('\n] as const;', start);
if (end < 0) fail('COMMON_ASSETS terminator not found');
const metadata = JSON.parse(source.slice(start + marker.length, end + 2));
const byId = new Map(metadata.map(asset => [asset.id.toLowerCase(), asset]));

const ID = /^56:0x[0-9a-f]{40}$/;
const seenIds = new Set();
const seenFeeds = new Set();
const assets = selected.assets.map(record => {
  const id = record.asset_id;
  if (!ID.test(id)) fail(`non-canonical asset_id ${id}`);
  if (seenIds.has(id)) fail(`duplicate asset_id ${id}`);
  if (seenFeeds.has(record.feed_id)) fail(`duplicate feed_id ${record.feed_id}`);
  seenIds.add(id);
  seenFeeds.add(record.feed_id);
  const meta = byId.get(id);
  if (!meta) fail(`no metadata for selected asset ${id} (${record.symbol})`);
  const feed = meta.atlas_feeds.find(candidate => candidate.feed_id === record.feed_id);
  if (!feed) fail(`metadata for ${id} has no feed ${record.feed_id}`);
  if (feed.quote_symbol !== 'USD') fail(`feed ${record.feed_id} is not USD-quoted`);
  if (meta.symbol.toUpperCase() === 'USDC') fail(`USDC must not be selected (${id})`);
  const logoPath = `/${meta.logo_path.replace(/^\/+/, '')}`;
  if (!existsSync(join(logoRoot, logoPath))) fail(`missing logo ${logoPath} for ${meta.symbol}`);
  const [category = 'CRYPTO', weighting = null] = feed.tags;
  return {
    id,
    chainId: meta.chain_id,
    address: meta.address,
    symbol: meta.symbol,
    name: meta.name,
    decimals: meta.decimals,
    logoPath,
    category: category.length <= 3 ? category : category[0] + category.slice(1).toLowerCase(),
    feedId: record.feed_id,
    feedName: feed.feed_name,
    feedWeighting: weighting,
    channel: record.channel,
  };
});
assets.sort((a, b) => a.symbol.localeCompare(b.symbol, 'en') || a.id.localeCompare(b.id));

const body = `/* Generated by scripts/generate-registry.mjs from backend/registry/selected.json
   and backend/registry/input/commonAssets.ts. Do not edit by hand; run
   \`pnpm registry:generate\`. Chain 56 reference assets with their verified Atlas
   feed. Asset-level identity only: not verified chain-97 collateral, not proof of
   backing or executable liquidity. */

export interface RegistryAsset {
  readonly id: string;
  readonly chainId: 56;
  readonly address: string;
  readonly symbol: string;
  readonly name: string;
  readonly decimals: number;
  readonly logoPath: string;
  readonly category: string;
  readonly feedId: number;
  readonly feedName: string;
  readonly feedWeighting: string | null;
  readonly channel: string;
}

export const REGISTRY_ASSETS: readonly RegistryAsset[] = ${JSON.stringify(assets, null, 2)};
`;

if (process.argv.includes('--check')) {
  const current = existsSync(outputPath) ? readFileSync(outputPath, 'utf8') : '';
  if (current !== body) fail('data/registry.generated.ts is out of date; run pnpm registry:generate');
  console.log(`generate-registry: up to date (${assets.length} assets)`);
} else {
  writeFileSync(outputPath, body);
  console.log(`generate-registry: wrote ${assets.length} assets to ${outputPath}`);
}
